  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 100000) return 'arr needs 1 to 10^5 values.';
  if (arr.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each value of arr is an integer between -10^5 and 10^5.';
  if (!Number.isInteger(k) || k < 1 || k > arr.length) return 'k is between 1 and arr.length.';
