function getStrongest(arr, k) {
  arr.sort((a, b) => a - b);
  const median = arr[Math.floor((arr.length - 1) / 2)];
  const result = [];
  let left = 0;
  let right = arr.length - 1;

  while (result.length < k) {
    const leftGap = Math.abs(arr[left] - median);
    const rightGap = Math.abs(arr[right] - median);
    if (rightGap >= leftGap) {
      result.push(arr[right]);
      right--;
    } else {
      result.push(arr[left]);
      left++;
    }
  }
  return result;
}

