function getStrongest(arr, k) {
  const sorted = [...arr].sort((a, b) => a - b);
  const m = sorted[(sorted.length - 1) >> 1];
  const ranked = [...arr].sort((x, y) => {
    const dx = Math.abs(x - m), dy = Math.abs(y - m);
    if (dx !== dy) return dy - dx;
    return y - x;
  });
  return ranked.slice(0, k);
}

